2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was likely caused by the introduction of `goto` statements in the previous commit, which complicated the control flow and error handling in the `modp_getbyname_esp` function. This made it difficult to manage the return values correctly, leading to potential incorrect behavior when handling null or empty input strings. The refactoring in the current patch aimed to simplify this logic and improve the overall readability and maintainability of the code.

        Commit message:
        alg_info.c: - fix bug introduced in
 8ca36783dd35b6ce7575a36dfa59e9ccb4deab9a - get rid of gotos - tidy  

        Patch:

 static int modp_getbyname_esp(const char *const str, int len)
 {
-	int ret = -1;
+	int ret;

-	if (!str || !*str)
-		goto out;
+	if (str == NULL || *str == '\0')
+		return -1;
 	ret = alg_enum_search(&oakley_group_names, "OAKLEY_GROUP_", "",
 				     str, len);
-	if (ret >= 0)
-		goto out;
-	ret = alg_enum_search(&oakley_group_names, "OAKLEY_GROUP_",
-				    " (extension)", str, len);
-out:
+	if (ret < 0)
+		ret = alg_enum_search(&oakley_group_names, "OAKLEY_GROUP_",
+				      " (extension)", str, len);
 	return ret;
 }

  */
 static void raw_alg_info_esp_add(struct alg_info_esp *alg_info,
 			       int ealg_id, unsigned ek_bits,
 			       int aalg_id, unsigned ak_bits)
 {
 	struct esp_info *esp_info = alg_info->esp;
 	unsigned cnt = alg_info->alg_info_cnt, i;

 	/*      check for overflows     */
 	passert(cnt < elemsof(alg_info->esp));
 	/*	dont add duplicates	*/
 	for (i = 0; i < cnt; i++)
-		if (    esp_info[i].esp_ealg_id == ealg_id &&
+		if (esp_info[i].esp_ealg_id == ealg_id &&
 			(!ek_bits || esp_info[i].esp_ealg_keylen == ek_bits) &&
 			esp_info[i].esp_aalg_id == aalg_id &&
 			(!ak_bits || esp_info[i].esp_aalg_keylen == ak_bits))
 			return;

 	esp_info[cnt].esp_ealg_id = ealg_id;
 	esp_info[cnt].esp_ealg_keylen = ek_bits;
 	esp_info[cnt].esp_aalg_id = aalg_id;
 	esp_info[cnt].esp_aalg_keylen = ak_bits;
 	/* sadb values */
 	esp_info[cnt].encryptalg = ealg_id;
 	esp_info[cnt].authalg = alg_info_esp_aa2sadb(aalg_id);
 	alg_info->alg_info_cnt++;
 	DBG(DBG_CRYPT, DBG_log("raw_alg_info_esp_add() "
 			       "ealg=%d aalg=%d cnt=%d",
 			       ealg_id, aalg_id, alg_info->alg_info_cnt));
 }


 static int parser_machine(struct parser_context *p_ctx)
 {
 	int ch = p_ctx->ch;

 	/* special 'absolute' cases */
 	p_ctx->err = "No error.";

 	/* chars that end algo strings */
 	switch (ch) {
 	case 0:         /* end-of-string */
 	case ',':       /* algo string separator */
 		switch (p_ctx->state) {
 		case ST_EA:
 		case ST_EK:
 		case ST_AA:
 		case ST_AK:
 		case ST_MODP:
-		default:
 		{
 			enum parser_state_esp next_state = 0;
+
 			switch (ch) {
 			case 0:   next_state = ST_EOF;
 				break;
 			case ',': next_state = ST_END;
 				break;
 			}
 			/* ch? parser_set_state(p_ctx, ST_END) : parser_set_state(p_ctx, ST_EOF) ; */
 			parser_set_state(p_ctx, next_state);
 			goto out;
 		}
+		default:
 			p_ctx->err = "String ended with invalid char";
 			goto err;
 		}
 	}
+
 re_eval:
 	switch (p_ctx->state) {
 	case ST_INI:
 		if (isspace(ch))
 			break;
 		if (isalnum(ch)) {
 			*(p_ctx->ealg_str++) = ch;
 			parser_set_state(p_ctx, ST_EA);
 			break;
 		}
 		p_ctx->err = "No alphanum. char initially found";
 		goto err;

 	case ST_INI_AA:
 		if (isspace(ch))
 			break;
 		if (isalnum(ch)) {
 			*(p_ctx->aalg_str++) = ch;
 			parser_set_state(p_ctx, ST_AA);
 			break;
 		}
 		p_ctx->err = "No alphanum. char initially found";
 		goto err;

 	case ST_EA:
 		if (isalpha(ch) || ch == '_') {
 			*(p_ctx->ealg_str++) = ch;
 			break;
 		}
 		if (isdigit(ch)) {
 			/* bravely switch to enc keylen */
 			*(p_ctx->ealg_str) = 0;
 			parser_set_state(p_ctx, ST_EK);
 			goto re_eval;
 		}
 		if (ch == '-') {
 			*(p_ctx->ealg_str) = 0;
 			parser_set_state(p_ctx, ST_EA_END);
 			break;
 		}
 		p_ctx->err = "No valid char found after enc alg string";
 		goto err;
 	case ST_EA_END:
 		if (isdigit(ch)) {
 			/* bravely switch to enc keylen */
 			parser_set_state(p_ctx, ST_EK);
 			goto re_eval;
 		}
 		if (isalpha(ch)) {
 			parser_set_state(p_ctx, ST_AA);
 			goto re_eval;
 		}
 		p_ctx->err = "No alphanum char found after enc alg separator";
 		goto err;
 	case ST_EK:
 		if (ch == '-') {
 			parser_set_state(p_ctx, ST_EK_END);
 			break;
 		}
 		if (isdigit(ch)) {
 			p_ctx->eklen = p_ctx->eklen * 10 + ch - '0';
 			break;
 		}
 		p_ctx->err =
 			"Non digit or valid separator found while reading enc keylen";
 		goto err;
 	case ST_EK_END:
 		if (isalpha(ch)) {
 			parser_set_state(p_ctx, ST_AA);
 			goto re_eval;
 		}
 		p_ctx->err =
 			"Non alpha char found after enc keylen end separator";
 		goto err;
 	case ST_AA:
 		if (ch == '-') {
 			*(p_ctx->aalg_str++) = 0;
 			parser_set_state(p_ctx, ST_AA_END);
 			break;
 		}
 		if (ch == ';') {
 			*(p_ctx->aalg_str++) = 0;
 			parser_set_state(p_ctx, ST_AK_END);
 			break;
 		}
 		if (isalnum(ch) || ch == '_') {
 			*(p_ctx->aalg_str++) = ch;
 			break;
 		}
 		p_ctx->err =
 			"Non alphanum or valid separator found in auth string";
 		goto err;
 	case ST_AA_END:
 		if (isdigit(ch)) {
 			parser_set_state(p_ctx, ST_AK);
 			goto re_eval;
 		}
 		/* Only allow modpXXXX string if we have
 		 * a modp_getbyname method
 		 */
 		if ((p_ctx->modp_getbyname) && isalpha(ch)) {
 			parser_set_state(p_ctx, ST_MODP);
 			goto re_eval;
 		}
 		p_ctx->err = "Non initial digit found for auth keylen";
 		goto err;
 	case ST_AK:
 		if (ch == '-' || ch == ';') {
 			parser_set_state(p_ctx, ST_AK_END);
 			break;
 		}
 		if (isdigit(ch)) {
 			p_ctx->aklen = p_ctx->aklen * 10 + ch - '0';
 			break;
 		}
 		p_ctx->err = "Non digit found for auth keylen";
 		goto err;
 	case ST_AK_END:
 		/* Only allow modpXXXX string if we have
 		 * a modp_getbyname method
 		 */
 		if ((p_ctx->modp_getbyname) && isalpha(ch)) {
 			parser_set_state(p_ctx, ST_MODP);
 			goto re_eval;
 		}
 		p_ctx->err = "Non alpha char found after auth keylen";
 		goto err;
 	case ST_MODP:
 		if (isalnum(ch)) {
 			*(p_ctx->modp_str++) = ch;
 			break;
 		}
 		p_ctx->err = "Non alphanum char found after in modp string";
 		goto err;
 	case ST_END:
 	case ST_EOF:
 	case ST_ERR:
 		break;
 		/* XXX */
 	}
 out:
 	return p_ctx->state;

 err:
 	parser_set_state(p_ctx, ST_ERR);
 	return ST_ERR;
 }


 static int parser_alg_info_add(struct parser_context *p_ctx,
 			       struct alg_info *alg_info,
 			       void (*alg_info_add)(struct alg_info *alg_info,
 						    int ealg_id, int ek_bits,
 						    int aalg_id, int ak_bits,
 						    int modp_id),
 			       const struct oakley_group_desc *(*lookup_group)(
 				       u_int16_t group))
 {
 	int ealg_id, aalg_id;
 	int modp_id = 0;

 	ealg_id = aalg_id = -1;
 	if (p_ctx->ealg_permit && *p_ctx->ealg_buf) {
 		ealg_id =
 			p_ctx->ealg_getbyname(p_ctx->ealg_buf,
 					      strlen(p_ctx->ealg_buf));
 #if 0
 		if (ealg_id == ESP_MAGIC_ID) {
 			ealg_id = p_ctx->eklen;
 			p_ctx->eklen = 0;
 		}
 #endif
 		if (ealg_id < 0) {
 			p_ctx->err = "enc_alg not found";
 			return -1;
 		}

 		/* AES CCM/GCM only allows 128, 192 or 256 bit key - excluding salt */
 		switch(ealg_id) {
 		case ESP_AES_GCM_8:
 		case ESP_AES_GCM_12:
 		case ESP_AES_GCM_16:
 		case ESP_AES_CCM_8:
 		case ESP_AES_CCM_12:
 		case ESP_AES_CCM_16:
-			if ( p_ctx->eklen != 128 &&
-			     p_ctx->eklen != 192 &&
-			     p_ctx->eklen != 256 ) {
+			if (p_ctx->eklen != 128 &&
+			    p_ctx->eklen != 192 &&
+			    p_ctx->eklen != 256) {
 				p_ctx->err =
 					"wrong encryption key length -"
 					" AES CCM/GCM only uses 128, 192 or 256";
 				return -1;
 			}
 		}

 		DBG(DBG_CRYPT, DBG_log("parser_alg_info_add() "
 				       "ealg_getbyname(\"%s\")=%d",
 				       p_ctx->ealg_buf,
 				       ealg_id));
 	}
 	if (p_ctx->aalg_permit && *p_ctx->aalg_buf) {
 		aalg_id =
 			p_ctx->aalg_getbyname(p_ctx->aalg_buf,
 					      strlen(p_ctx->aalg_buf));
 		if (aalg_id < 0) {
 			p_ctx->err = "hash_alg not found";
 			return -1;
 		}

 		DBG(DBG_CRYPT, DBG_log("parser_alg_info_add() "
 				       "aalg_getbyname(\"%s\")=%d",
 				       p_ctx->aalg_buf,
 				       aalg_id));
 	}
 	if (p_ctx->modp_getbyname && *p_ctx->modp_buf) {
 		modp_id =
 			p_ctx->modp_getbyname(p_ctx->modp_buf,
 					      strlen(p_ctx->modp_buf));
 		if (modp_id < 0) {
 			p_ctx->err = "modp group not found";
 			return -1;
 		}

 		DBG(DBG_CRYPT, DBG_log("parser_alg_info_add() "
 				       "modp_getbyname(\"%s\")=%d",
 				       p_ctx->modp_buf,
 				       modp_id));

 		if (modp_id && !lookup_group(modp_id)) {
 			p_ctx->err = "found modp group id, but not supported";
 			return -1;
 		}
 	}

 	(*alg_info_add)(alg_info,
 			ealg_id, p_ctx->eklen,
 			aalg_id, p_ctx->aklen,
 			modp_id);
 	return 0;
 }

 /*	snprint already parsed transform list (alg_info)	*/
 int alg_info_snprint(char *buf, int buflen,
 		     const struct alg_info *alg_info)
 {
 	char *ptr = buf;
 	struct esp_info *esp_info;
 	struct ike_info *ike_info;

 	passert(buflen > 0);

 	int cnt;
 	ptr = buf;
 	switch (alg_info->alg_info_protoid) {
 	case PROTO_IPSEC_ESP:
 	{
 		struct alg_info_esp *alg_info_esp =
 			(struct alg_info_esp *)alg_info;
 		ALG_INFO_ESP_FOREACH(alg_info_esp, esp_info, cnt) {
 			snprintf(ptr, buflen, "%s(%d)_%03d-%s(%d)_%03d",
 				 enum_name(&esp_transformid_names,
 					   esp_info->esp_ealg_id) +
 				 sizeof("ESP"),
 				 esp_info->esp_ealg_id,
 				 (int)esp_info->esp_ealg_keylen,
 				 enum_name(&auth_alg_names,
 					   esp_info->esp_aalg_id) +
 				 (esp_info->esp_aalg_id ?
 					sizeof("AUTH_ALGORITHM_HMAC") :
 					sizeof("AUTH_ALGORITHM")),
 				 esp_info->esp_aalg_id,
 				 (int)esp_info->esp_aalg_keylen);
 			size_t np = strlen(ptr);
 			ptr += np;
 			buflen -= np;
-			if ( cnt > 0) {
+			if (cnt > 0) {
 				snprintf(ptr, buflen, ", ");
 				np = strlen(ptr);
 				ptr += np;
 				buflen -= np;
 			}
 			if (buflen <= 0)
 				goto out;
 		}
 		if (alg_info_esp->esp_pfsgroup) {
 			snprintf(ptr, buflen, "; pfsgroup=%s(%d)",
 				 enum_name(&oakley_group_names,
 					   alg_info_esp->esp_pfsgroup) +
 				 sizeof("OAKLEY_GROUP"),
 				 alg_info_esp->esp_pfsgroup);
 			size_t np = strlen(ptr);
 			ptr += np;
 			buflen -= np;
-			if (buflen <= 0)
-				goto out;
 		}
 		break;
 	}

 	case PROTO_IPSEC_AH:
 	{
 		struct alg_info_esp *alg_info_esp =
 			(struct alg_info_esp *)alg_info;
 		ALG_INFO_ESP_FOREACH(alg_info_esp, esp_info, cnt) {
 			snprintf(ptr, buflen, "%s(%d)_%03d",
 				 enum_name(&auth_alg_names,
 					   esp_info->esp_aalg_id) +
 				 sizeof("AUTH_ALGORITHM_HMAC"),
 				 esp_info->esp_aalg_id,
 				 (int)esp_info->esp_aalg_keylen);
 			size_t np = strlen(ptr);
 			ptr += np;
 			buflen -= np;
-			if ( cnt > 0) {
+			if (cnt > 0) {
 				snprintf(ptr, buflen, ", ");
 				np = strlen(ptr);
 				ptr += np;
 				buflen -= np;
 			}
 			if (buflen <= 0)
 				goto out;
 		}
 		if (alg_info_esp->esp_pfsgroup) {
 			snprintf(ptr, buflen, "; pfsgroup=%s(%d)",
 				 enum_name(&oakley_group_names,
 					   alg_info_esp->esp_pfsgroup) +
 				 sizeof("OAKLEY_GROUP"),
 				 alg_info_esp->esp_pfsgroup);
 			size_t np = strlen(ptr);
 			ptr += np;
 			buflen -= np;
-			if (buflen <= 0)
-				goto out;
 		}
 		break;
 	}

 	case PROTO_ISAKMP:
 		{
 			ALG_INFO_IKE_FOREACH((struct alg_info_ike *)alg_info,
 					     ike_info, cnt) {
 				snprintf(ptr, buflen,
 					 "%s(%d)_%03d-%s(%d)_%03d-%s(%d)",
 					 enum_name(&oakley_enc_names,
 						   ike_info->ike_ealg) +
 					 sizeof("OAKLEY"),
 					 ike_info->ike_ealg,
 					 (int)ike_info->ike_eklen,
 					 enum_name(&oakley_hash_names,
 						   ike_info->ike_halg) +
 					 sizeof("OAKLEY"),
 					 ike_info->ike_halg,
 					 (int)ike_info->ike_hklen,
 					 enum_name(&oakley_group_names,
 						   ike_info->ike_modp) +
 					 sizeof("OAKLEY_GROUP"),
 					 ike_info->ike_modp);
 				size_t np = strlen(ptr);
 				ptr += np;
 				buflen -= np;
-				if ( cnt > 0) {
+				if (cnt > 0) {
 					snprintf(ptr, buflen, ", ");
 					np = strlen(ptr);
 					ptr += np;
 					buflen -= np;
 				}
 				if (buflen <= 0)
-					goto out;
+					break;
 			}
 			break;
 		}
-	/* FALLTHROUGH */

 	default:
 		snprintf(buf, buflen, "INVALID protoid=%d\n",
 			 alg_info->alg_info_protoid);
 		size_t np = strlen(ptr);
 		ptr += np;
 		buflen -= np;
-		goto out;
+		break;
 	}

 out:
 	passert(buflen >= 0);

 	return ptr - buf;
 }
